<script setup lang="ts">
const platformApi = uni
import {ref} from 'vue';import {onLoad} from '@dcloudio/uni-app';import PageShell from '../../components/PageShell.vue';import {usePage} from '../../composables/usePage';import {request,upload} from '../../utils/request';import {go,time,status,checks,confirm,toast} from '../../utils/format';const id=ref(0),order=ref<any>(null),media=ref<any[]>([]),quantity=ref<Record<string,string>>({}),notes=ref<Record<string,string>>({});onLoad(q=>id.value=Number(q?.id));const {loading,error,load,busy,action}=usePage(async()=>{[order.value,media.value]=await Promise.all([request('/orders/'+id.value),request('/orders/'+id.value+'/media')]);for(const c of order.value.checklist){quantity.value[c.code]=c.quantity==null?'':String(c.quantity);notes.value[c.code]=c.notes||''}});async function change(c:any){await request('/orders/'+id.value+'/checklist','PUT',{code:c.code,completed:!c.completed,quantity:quantity.value[c.code]?Number(quantity.value[c.code]):null,unit:c.code==='PLAY'?'MINUTE':c.code==='FEED'?'GRAM':c.code==='WATER'?'ML':null,notes:notes.value[c.code]});await load()}async function checkin(){if(await confirm('确认已到达服务地址并准备进门？系统将通知宠主。')){await request('/orders/'+id.value+'/checkin','POST');await load()}}async function complete(){if(await confirm('请确认服务清单已完成、门窗已关闭、录像已上传。完成后将通知宠主并生成服务记录。')){await request('/orders/'+id.value+'/complete','POST');uni.redirectTo({url:'/pages/sitter/done?id='+id.value})}}function photo(){uni.chooseImage({count:1,sourceType:['camera','album'],success:r=>action(async()=>{await upload(id.value,r.tempFilePaths[0]);await load()},'照片已上传'),fail:()=>toast('未选择照片')})}function video(){uni.chooseVideo({sourceType:['camera','album'],maxDuration:600,success:r=>action(async()=>{await upload(id.value,r.tempFilePath);await load()},'录像已上传'),fail:()=>toast('未选择录像')})}async function respond(accept:boolean){await request('/orders/'+id.value+'/'+(accept?'accept':'reject'),'POST');await load()}
</script><template><PageShell title="服务执行" back :loading="loading" :error="error" @retry="load"><template v-if="order"><view class="row"><view class="title">把每一步，做好。</view><text class="pill">{{status(order.status)}}</text></view><view class="card" style="margin-top:20px"><view style="font-weight:700">{{order.pet_snapshot?.map((p:any)=>p.name).join('、')}}</view><text class="muted">{{time(order.service_start)}}</text><view class="divider"/><view>{{order.address_snapshot?.district}} · {{order.address_snapshot?.address}}</view><view class="link" @click="platformApi.makePhoneCall({phoneNumber:order.address_snapshot.phone})">{{order.address_snapshot?.contact_name}} · {{order.address_snapshot?.phone}}</view><view class="notice warning" style="margin:14px 0 0">{{order.notes||'暂无额外服务备注，请核对宠物档案与服务项目。'}}</view><view v-for="p in order.pet_snapshot" :key="p.id" style="margin-top:12px"><text style="font-weight:700">{{p.name}}</text><view class="muted">饮食：{{p.dietary_notes||'未填写'}} · 病史：{{p.medical_history||'未填写'}} · 性格：{{p.temperament||'未填写'}}</view></view></view><view v-if="order.status==='PENDING_ACCEPT'" class="inline-actions"><button class="outline" :disabled="busy" @click="action(()=>respond(false),'已拒单')">拒绝</button><button class="primary" :disabled="busy" @click="action(()=>respond(true),'接单成功')">确认接单</button></view><button v-if="order.status==='ACCEPTED'" class="primary" :disabled="busy" @click="action(checkin,'')">开始进门打卡</button><template v-if="order.status==='SERVICING'"><view class="section">标准照护清单 <text class="muted">逐项确认，真实记录</text></view><view v-for="c in order.checklist" :key="c.code" class="card"><view class="row"><text style="font-weight:700">{{checks[c.code]}}</text><text class="pill" :class="{green:c.completed}">{{c.completed?'已完成':'待完成'}}</text></view><view v-if="['FEED','WATER','PLAY'].includes(c.code)" class="field" style="margin-top:12px"><input v-model="quantity[c.code]" type="digit" :placeholder="c.code==='PLAY'?'实际陪玩分钟数（至少 10 分钟）':c.code==='FEED'?'实际喂食量（克）':'实际换水量（毫升）'"/></view><view class="field" style="margin-top:12px"><input v-model="notes[c.code]" placeholder="填写现场记录（可选）"/></view><button class="secondary" :disabled="busy" @click="action(()=>change(c),'清单已保存')">{{c.completed?'撤销完成':'确认已完成'}}</button></view><view class="section">照片与服务录像</view><view class="notice warning">请上传真实服务录像后再完成服务。此处为文件上传，不代表后台自动持续录像或直播。</view><view class="inline-actions"><button class="outline" :disabled="busy" @click="photo">拍照 / 上传照片</button><button class="secondary" :disabled="busy" @click="video">录制 / 上传录像</button></view><view class="card" style="margin-top:14px"><view v-for="m in media" :key="m.id" class="menu-item">{{m.kind==='VIDEO'?'▷ 录像':'▧ 照片'}} #{{m.id}}<text class="pill green">已上传</text></view><text v-if="!media.length" class="muted">尚未上传媒体</text></view><button class="outline full-width" @click="go('owner/emergency?orderId='+id)">上报异常 / 送医协助</button><button class="primary" style="margin-top:16px" :disabled="busy" @click="action(complete,'服务已完成')">确认离门并完成服务</button></template><button v-if="order.status==='COMPLETED'" class="primary" @click="go('sitter/done?id='+id)">查看完成回执</button><button class="outline full-width" style="margin-top:14px" @click="go('owner/service?orderId='+id)">进入服务群</button></template></PageShell></template>

